// src/screens/HomeScreen.js - упрощенный главный экран для диагностики
import React from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  StyleSheet, 
  ScrollView,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const HomeScreen = ({ navigation }) => {

  // Убедитесь, что navigation передается корректно
  if (!navigation) {
    return <View style={styles.container}><Text style={styles.errorText}>Ошибка: Свойство навигации не передано.</Text></View>;
  }

  const NavigationButton = ({ title, screenName, icon, color }) => (
    <TouchableOpacity 
      style={[styles.navButton, { backgroundColor: color }]} 
      onPress={() => navigation.navigate(screenName)}
    >
      <Ionicons name={icon} size={20} color="white" />
      <Text style={styles.navButtonText}>{title}</Text>
    </TouchableOpacity>
  );

  return (
    <ScrollView style={styles.container}>

      {/* Секция Навигации */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Навигация по приложению (Проверка)</Text>
        <Text style={styles.statusText}>
          Если вы видите этот текст, главный экран загрузился успешно! 
          Проблема была в сложной логике API/State.
        </Text>

        <View style={styles.navRow}>
          <NavigationButton 
            title="Мультимедиа" 
            screenName="Media" 
            icon="camera" 
            color="#34C759"
          />
          <NavigationButton 
            title="Галерея" 
            screenName="Gallery" 
            icon="images" 
            color="#007AFF"
          />
        </View>
        <View style={styles.navRow}>
          <NavigationButton 
            title="Аналитика" 
            screenName="Analytics" 
            icon="analytics" 
            color="#FF9500"
          />
          <NavigationButton 
            title="Настройки" 
            screenName="Settings" 
            icon="settings" 
            color="#5856D6"
          />
        </View>
      </View>

      {/* Пустое место, чтобы показать, что больше нет сложного кода */}
      <View style={styles.emptyContent}>
        <Text style={styles.emptyText}>Упрощенная версия загружена.</Text>
      </View>

    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f5f5f5',
  },
  section: {
    backgroundColor: 'white',
    margin: 10,
    borderRadius: 12,
    padding: 15,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
    marginBottom: 15,
  },
  sectionTitle: {
    fontSize: 18,
    fontWeight: 'bold',
    marginBottom: 10,
    color: '#333',
    borderBottomWidth: 1,
    borderBottomColor: '#f0f0f0',
    paddingBottom: 5,
    textAlign: 'center',
  },
  statusText: {
    marginTop: 15,
    marginBottom: 15,
    fontSize: 14,
    color: '#34C759',
    textAlign: 'center',
    fontWeight: '600',
  },
  navRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 10,
  },
  navButton: {
    paddingHorizontal: 15,
    paddingVertical: 12,
    borderRadius: 8,
    alignItems: 'center',
    flex: 1,
    marginHorizontal: 5,
    flexDirection: 'row',
    justifyContent: 'center',
    gap: 8,
  },
  navButtonText: {
    color: 'white',
    fontSize: 14,
    fontWeight: '600',
  },
  emptyContent: {
    padding: 50,
    alignItems: 'center',
  },
  emptyText: {
    color: '#ccc',
    fontSize: 16,
  },
  errorText: {
    color: '#FF3B30',
    fontSize: 20,
    textAlign: 'center',
    margin: 40,
  }
});

export default HomeScreen;
